#!/usr/bin/env python3
# coding: utf-8

# Copyright (C) 2017-present Robert Griesel
# This program is free software: you can redistribute it and/or modify
# it under the terms of the GNU General Public License as published by
# the Free Software Foundation, either version 3 of the License, or
# (at your option) any later version.
# 
# This program is distributed in the hope that it will be useful,
# but WITHOUT ANY WARRANTY; without even the implied warranty of
# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the
# GNU General Public License for more details.
# 
# You should have received a copy of the GNU General Public License
# along with this program. If not, see <http://www.gnu.org/licenses/>

import gi
gi.require_version('Gtk', '4.0')
gi.require_version('Adw', '1')
from gi.repository import Adw, Gdk, Gtk
import os
import sys

class ColorManager:
    main_window = None
    cached_colors = {}
    debug_mode = True  # Set to True to enable theme debugging

    @classmethod
    def init(cls, main_window):
        cls.main_window = main_window

        # Get style manager and track dark mode state
        style_manager = Adw.StyleManager.get_default()
        cls.is_dark_mode = style_manager.get_dark()

        # Debug info
        if cls.debug_mode:
            print(f"ColorManager initialized. Dark mode: {cls.is_dark_mode}")
            print(f"Color scheme: {style_manager.get_color_scheme()}")

        # Connect to style changes but mark as disabled (will just log)
        style_manager.connect('notify::dark', cls.on_color_scheme_changed)

        # Update window classes based on current theme
        cls.update_window_theme_classes()

    @classmethod
    def update_window_theme_classes(cls):
        """Update window CSS classes based on theme"""
        if not cls.main_window:
            return

        # Get current theme state
        style_manager = Adw.StyleManager.get_default()
        cls.is_dark_mode = style_manager.get_dark()

        # Update classes
        if cls.is_dark_mode:
            cls.main_window.add_css_class("dark")
            cls.main_window.remove_css_class("light")
        else:
            cls.main_window.add_css_class("light")
            cls.main_window.remove_css_class("dark")

        # Force redraw
        cls.main_window.queue_draw()

    @classmethod
    def on_color_scheme_changed(cls, style_manager, pspec):
        """Handler for theme changes - ONLY logs, does not modify theme"""
        print("ColorManager.on_color_scheme_changed called (disabled)")

        # Clear color cache
        cls.cached_colors = {}

        # Update dark mode state
        cls.is_dark_mode = style_manager.get_dark()

        # Update window theme classes
        cls.update_window_theme_classes()
        cls.connect_style_manager()

        # Debug output
        if cls.debug_mode:
            print(f"Theme changed to: {'dark' if cls.is_dark_mode else 'light'}")
            print(f"Is dark theme now: {cls.is_dark_mode}")

    @classmethod
    def get_ui_color(cls, name):
        """Get a UI color by name with caching"""
        # Check cache first for performance
        if name in cls.cached_colors:
            return cls.cached_colors[name]

        # Get color from style context
        if cls.main_window:
            style_context = cls.main_window.get_style_context()
            success, rgba = style_context.lookup_color(name)
            if success:
                cls.cached_colors[name] = rgba
                return rgba

        # Return fallback color if lookup fails
        return cls.get_fallback_color(name)

    @classmethod
    def get_fallback_color(cls, name):
        """Provide fallback colors when theme lookups fail"""
        # Get current theme mode
        is_dark = Adw.StyleManager.get_default().get_dark()

        if name == 'theme_fg_color':
            return Gdk.RGBA(1.0, 1.0, 1.0, 1.0) if is_dark else Gdk.RGBA(0.0, 0.0, 0.0, 1.0)
        elif name == 'theme_bg_color':
            return Gdk.RGBA(0.2, 0.2, 0.2, 1.0) if is_dark else Gdk.RGBA(1.0, 1.0, 1.0, 1.0)
        elif name == 'theme_selected_bg_color':
            return Gdk.RGBA(0.25, 0.5, 0.9, 1.0)
        elif name == 'theme_selected_fg_color':
            return Gdk.RGBA(1.0, 1.0, 1.0, 1.0)
        elif name == 'theme_text_color':
            return Gdk.RGBA(1.0, 1.0, 1.0, 1.0) if is_dark else Gdk.RGBA(0.0, 0.0, 0.0, 1.0)
        elif name == 'theme_base_color':
            return Gdk.RGBA(0.15, 0.15, 0.15, 1.0) if is_dark else Gdk.RGBA(1.0, 1.0, 1.0, 1.0)
        else:
            # Default fallback color
            return Gdk.RGBA(0.5, 0.5, 0.5, 1.0)

    @classmethod
    def get_ui_color_string(cls, name):
        """Get a UI color as a hex string"""
        color_rgba = cls.get_ui_color(name)
        color_string = '#'
        color_string += format(int(color_rgba.red * 255), '02x')
        color_string += format(int(color_rgba.green * 255), '02x')
        color_string += format(int(color_rgba.blue * 255), '02x')
        return color_string

    @classmethod
    def get_ui_color_string_with_alpha(cls, name):
        """Get a UI color as a hex string with alpha"""
        color_rgba = cls.get_ui_color(name)
        color_string = '#'
        color_string += format(int(color_rgba.red * 255), '02x')
        color_string += format(int(color_rgba.green * 255), '02x')
        color_string += format(int(color_rgba.blue * 255), '02x')
        color_string += format(int(color_rgba.alpha * 255), '02x')
        return color_string

